  var STORAGE_KEY = 'calculator-theme';
  var VALID_THEMES = ['light', 'dark'];
  // Explicit default theme, since the spec leaves the default undecided.
  var DEFAULT_THEME = 'light';

  function getStoredTheme() {
    var stored = null;
    try {
      stored = window.localStorage.getItem(STORAGE_KEY);
    } catch (error) {
      stored = null;
    }
    return VALID_THEMES.indexOf(stored) !== -1 ? stored : DEFAULT_THEME;
  }

  function applyTheme(theme) {
    var resolved = VALID_THEMES.indexOf(theme) !== -1 ? theme : DEFAULT_THEME;
    document.documentElement.setAttribute('data-theme', resolved);
    return resolved;
  }

  function storeTheme(theme) {
    try {
      window.localStorage.setItem(STORAGE_KEY, theme);
    } catch (error) {
      // localStorage unavailable (e.g. private browsing); theme just won't persist.
    }
  }

  applyTheme(getStoredTheme());

  function reflectToggleState(toggle, theme) {
    var isDark = theme === 'dark';
    toggle.setAttribute('aria-pressed', String(isDark));
    var label = toggle.querySelector('.theme-toggle-label');
    var icon = toggle.querySelector('.theme-toggle-icon');
    if (label) {
      label.textContent = isDark ? 'Light Mode' : 'Dark Mode';
    }
    if (icon) {
      icon.textContent = isDark ? '☀️' : '\U0001f319';
    }
  }

  function setUpToggle() {
    var toggle = document.getElementById('theme-toggle');
    if (!toggle) {
      return;
    }

    reflectToggleState(toggle, document.documentElement.getAttribute('data-theme'));

    toggle.addEventListener('click', function () {
      var current = document.documentElement.getAttribute('data-theme');
      var next = current === 'dark' ? 'light' : 'dark';
      applyTheme(next);
      storeTheme(next);
      reflectToggleState(toggle, next);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setUpToggle);
  } else {
    setUpToggle();
  }
})();
