  var display = document.getElementById('display');

  var state = {
    currentInput: '0',
    previousValue: null,
    operator: null,
    overwrite: false,
  };

  function updateDisplay() {
    display.textContent = state.currentInput;
  }

  function inputDigit(digit) {
    if (state.overwrite) {
      state.currentInput = digit === '0' ? '0' : digit;
      state.overwrite = false;
      updateDisplay();
      return;
    }
    if (state.currentInput === '0') {
      state.currentInput = digit;
    } else {
      state.currentInput += digit;
    }
    updateDisplay();
  }

  function inputDecimal() {
    if (state.overwrite) {
      state.currentInput = '0.';
      state.overwrite = false;
      updateDisplay();
      return;
    }
    if (state.currentInput.indexOf('.') === -1) {
      state.currentInput += '.';
      updateDisplay();
    }
  }

  function clear() {
    state.currentInput = '0';
    state.previousValue = null;
    state.operator = null;
    state.overwrite = false;
    updateDisplay();
  }

  function backspace() {
    if (state.overwrite) {
      return;
    }
    var isSingleCharacter = state.currentInput.length <= 1;
    var isLoneNegativeSign = state.currentInput.length === 2 && state.currentInput.charAt(0) === '-';
    if (isSingleCharacter || isLoneNegativeSign) {
      state.currentInput = '0';
    } else {
      state.currentInput = state.currentInput.slice(0, -1);
    }
    updateDisplay();
  }

  function compute(a, b, operator) {
    switch (operator) {
      case '+':
        return a + b;
      case '-':
        return a - b;
      case '*':
        return a * b;
      case '/':
        // Division by zero is undefined by the spec; treated as an error result.
        return b === 0 ? NaN : a / b;
      default:
        return b;
    }
  }

  function formatResult(value) {
    if (!isFinite(value)) {
      return 'Error';
    }
    var rounded = Math.round(value * 1e10) / 1e10;
    return String(rounded);
  }

  function chooseOperator(nextOperator) {
    var inputValue = parseFloat(state.currentInput);

    if (state.operator !== null && state.overwrite) {
      state.operator = nextOperator;
      return;
    }

    if (state.previousValue === null) {
      state.previousValue = inputValue;
    } else if (state.operator !== null) {
      var result = compute(state.previousValue, inputValue, state.operator);
      state.previousValue = result;
      state.currentInput = formatResult(result);
      updateDisplay();
    }

    state.operator = nextOperator;
    state.overwrite = true;
  }

  function equals() {
    if (state.operator === null || state.previousValue === null) {
      return;
    }
    var inputValue = parseFloat(state.currentInput);
    var result = compute(state.previousValue, inputValue, state.operator);
    state.currentInput = formatResult(result);
    state.previousValue = null;
    state.operator = null;
    state.overwrite = true;
    updateDisplay();
  }

  var actions = {
    digit: function (button) {
      inputDigit(button.getAttribute('data-digit'));
    },
    decimal: function () {
      inputDecimal();
    },
    operator: function (button) {
      chooseOperator(button.getAttribute('data-operator'));
    },
    clear: function () {
      clear();
    },
    backspace: function () {
      backspace();
    },
    equals: function () {
      equals();
    },
  };

  var buttons = document.querySelectorAll('.keypad .btn');
  for (var i = 0; i < buttons.length; i += 1) {
    (function (button) {
