        var action = actions[button.getAttribute('data-action')];
        if (action) {
          action(button);
        }
      });
    })(buttons[i]);
  }

  var KEY_TO_OPERATOR = {
    '+': '+',
    '-': '-',
    '*': '*',
    '/': '/',
  };

